const fs = require('fs');

// Recover file path from trigger (same pattern as ingest workflow)
let filePath = null;
try {
  const triggerData = $('Watch Output Files').first().json;
  filePath = triggerData?.path ?? triggerData?.filename ?? null;
} catch(e) {}

if (!filePath || !filePath.endsWith('.md')) return [];

let content;
try {
  content = fs.readFileSync(filePath, 'utf8');
} catch (e) {
  return [];
}

// Parse YAML frontmatter
const parts = content.split(/(?:^|\n)---\n/);
if (parts.length < 3) return [];

const meta = {};
for (const line of parts[1].trim().split('\n')) {
  const match = line.match(/^([\w_]+):\s*(.+)$/);
  if (match) {
    let val = match[2].trim().replace(/^"|"$/g, '');
    if (val === 'true') val = true;
    else if (val === 'false') val = false;
    meta[match[1]] = val;
  }
}

if (meta.approved !== true) return [];
if (meta.applied_at) return [];

const feedbackRef = meta.feedback_ref;
if (!feedbackRef) throw new Error('approved output file missing feedback_ref: ' + filePath);

const feedback = JSON.parse(fs.readFileSync('/data/vault/' + feedbackRef, 'utf8'));

return [{ json: { approved: true, feedback, output_file_path: filePath } }];

const input = $input.first().json;
const body = input.body ?? input;
const feedback = body.feedback ?? body;
if (!feedback.output_id) {
  feedback.output_id = 'out-' + new Date().toISOString().slice(0, 10) + '-manual-feedback';
}
if (!feedback.decision) {
  feedback.decision = 'output_only';
}
if (!Array.isArray(feedback.candidate_items)) {
  feedback.candidate_items = [];
}
const approved = body.approved === true || feedback.approved === true || body.approved === 'true' || feedback.approved === 'true';
if (feedback.decision === 'propagate' && !approved) {
  throw new Error('Human approval required: send approved=true with propagate feedback before applying wiki changes.');
}
delete feedback.approved;
return [{
  json: {
    approved,
    feedback,
    output_file_path: body.output_file_path ?? null,
    payload_b64: Buffer.from(JSON.stringify(feedback), 'utf8').toString('base64')
  }
}];

const stdout = $input.first().json.stdout ?? '';
if (!stdout.trim()) {
  throw new Error('feedback-record.ts returned empty stdout');
}
return [{ json: JSON.parse(stdout) }];

const stdout = $input.first().json.stdout ?? '';
if (!stdout.trim()) {
  throw new Error('apply-update.ts returned empty stdout');
}
return [{ json: JSON.parse(stdout) }];

const stdout = $input.first().json.stdout ?? '';
if (!stdout.trim()) {
  throw new Error('reindex.ts returned empty stdout');
}
return [{ json: JSON.parse(stdout) }];

const feedback = $node["Parse Feedback Result"].json;
const mutation = $node["Parse Mutation Result"].json;
const payload = {
  operation: 'feedback',
  summary: `Propagate feedback for ${feedback.record.output_id}`,
  source_refs: feedback.record.source_refs ?? [],
  affected_notes: feedback.record.affected_notes ?? [],
  paths_to_stage: [
    feedback.record_path,
    feedback.summary_path,
    ...(feedback.mutation_plan_path ? [feedback.mutation_plan_path] : []),
    ...mutation.created,
    ...mutation.updated,
    'state/runtime/idempotency-keys.json'
  ],
  feedback_record_ref: feedback.record_path,
  commit_message: `feedback: ${feedback.record.output_id}`
};
return [{
  json: {
    payload,
    payload_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64')
  }
}];

const stdout = $input.first().json.stdout ?? '';
if (!stdout.trim()) {
  throw new Error('commit.ts returned empty stdout');
}
return [{ json: JSON.parse(stdout) }];

return [{
  json: {
    status: 'feedback_recorded',
    decision: $node["Parse Feedback Result"].json.record.decision,
    feedback_record: $node["Parse Feedback Result"].json.record,
    feedback_record_path: $node["Parse Feedback Result"].json.record_path,
    summary_path: $node["Parse Feedback Result"].json.summary_path,
    mutation_plan_path: $node["Parse Feedback Result"].json.mutation_plan_path
  }
}];

return [{
  json: {
    status: 'feedback_propagated',
    feedback_record: $node["Parse Feedback Result"].json.record,
    feedback_record_path: $node["Parse Feedback Result"].json.record_path,
    mutation_plan_path: $node["Parse Feedback Result"].json.mutation_plan_path,
    mutation_result: $node["Parse Mutation Result"].json,
    reindex_result: $node["Parse Reindex Result"].json,
    commit_result: $node["Parse Commit Result"].json
  }
}];

const fs = require('fs');
let outputFilePath = null;
try {
  outputFilePath = $node['Prepare Feedback Payload'].json.output_file_path;
} catch(e) {}

if (outputFilePath) {
  try {
    let content = fs.readFileSync(outputFilePath, 'utf8');
    const ts = new Date().toISOString();
    content = content.replace(/^approved: (true|false)$/m, `applied_at: "${ts}"`);
    fs.writeFileSync(outputFilePath, content, 'utf8');
  } catch(e) {
    // Non-fatal: log but don't fail the workflow
    console.warn('Mark Applied: could not update output file', outputFilePath, e.message);
  }
}

return [$input.first()];
